    for i in range(H):
        for j in range(W):
            if inp[i,j]==marker: continue
            kk=(i%pr,j%pc)
            if kk not in M: M[kk]=int(inp[i,j])
    return [[M[(i%pr,j%pc)] for j in range(W)] for i in range(H)]
